:root {
  color-scheme: dark;
  --ink:#0b0b11;
  --paper:#f5f2fa;
  --muted:#aaa6b9;
  --blue:#629dff;
  --red:#ff566f;
  --line:#ffffff20;
  --gold:#f7ed72;
  font-family: Inter, system-ui, sans-serif;
  background:var(--ink);
  color:var(--paper);
}
* { box-sizing:border-box; }
body { margin:0; }
button { font:inherit; font-weight:650; color:inherit; background:#ffffff0b; border:1px solid var(--line); border-radius:8px; padding:.72rem 1rem; cursor:pointer; }
button:hover, button[aria-pressed=true], button.active { background:#ffffff18; color:white; }
button:focus-visible { outline:3px solid var(--gold); outline-offset:4px; }
.shell { min-height:100vh; display:grid; grid-template-rows:auto 1fr auto; }
header, footer { display:flex; align-items:center; justify-content:space-between; gap:1rem; padding:1.05rem clamp(1rem,5vw,6rem); background:#0c0c13; }
header { border-bottom:1px solid var(--line); }
footer { justify-content:center; flex-wrap:wrap; border-top:1px solid var(--line); color:var(--muted); font-size:.8rem; }
nav { display:flex; gap:.25rem; }
nav[hidden] { display:none; }
nav button, .brand { border-color:transparent; background:transparent; }
.brand { font-weight:950; white-space:nowrap; padding-left:0; }
.brand i, h1 em { color:var(--gold); }
.mark { color:var(--gold); margin-right:.5rem; }
main { position:relative; min-width:0; text-align:center; padding:clamp(1.5rem,4vw,5rem) 1rem; }
h1,h2,p { margin:0; }
h1 { font-size:clamp(2rem,5vw,5rem); line-height:1; }
.home, .intro, .versus, .winner, .roulette, .result {
  background:
    radial-gradient(ellipse at 14% 60%, #2456a760, transparent 51%),
    radial-gradient(ellipse at 86% 60%, #a91c3360, transparent 51%),
    repeating-linear-gradient(0deg, transparent 0 5px, #ffffff04 6px 7px),
    #0e0e18;
}
.home { display:flex; flex-direction:column; align-items:center; justify-content:center; gap:clamp(1.5rem,4vh,3rem); }
.hero h1, .intro-title { font-size:clamp(2.85rem,8.4vw,11rem); font-family: "Barlow Condensed", Impact, sans-serif; font-style:italic; font-weight:900; letter-spacing:-.038em; text-shadow:0 10px 70px #000; }
h1 em { font-style:inherit; }
.eyebrow { color:var(--gold); letter-spacing:.23em; font-weight:850; font-size:.8rem; margin-bottom:.9rem; }
.subtitle { color:var(--muted); font-size:clamp(.95rem,1.5vw,1.35rem); margin-top:.9rem; }
.matchup { display:grid; grid-template-columns:1fr auto 1fr; width:min(62rem,100%); align-items:center; gap:clamp(.4rem,3vw,2.25rem); }
.player { --team:var(--blue); background:linear-gradient(145deg,#ffffff0a,#0004); border:1px solid var(--line); border-bottom:2px solid var(--team); border-radius:14px; padding:clamp(.8rem,3vw,2.6rem); }
.player.red, .reels .red { --team:var(--red); }
.avatar { color:var(--team); font-size:clamp(2rem,5vw,4.5rem); text-shadow:0 0 30px var(--team); line-height:1; margin-bottom:.75rem; }
.player h2 { font-size:clamp(1.05rem,3vw,2.25rem); }
.player p { color:var(--muted); margin-top:.35rem; }
.home-vs,.duel-vs { font-family:Impact,sans-serif; font-style:italic; font-size:clamp(1.5rem,5vw,5rem); color:var(--gold); }
.fight,.primary { color:#15130a; background:var(--gold); border:0; font-weight:950; }
.fight { font-size:clamp(1.5rem,3vw,2.8rem); font-style:italic; min-width:min(21rem,90%); box-shadow:0 0 46px #f9ee743c; }
.fight span { margin-left:1rem; }
.fight:hover,.primary:hover { background:#fff7a2; color:#15130a; }
.intro,.result { display:grid; place-items:center; }
.intro-title { animation:appear 1.5s both; }
@keyframes appear { from { opacity:0; transform:scale(.85); } to { opacity:1; transform:scale(1); } }
.poster-art { position:relative; display:grid; place-items:center; width:100%; aspect-ratio:2/3; overflow:hidden; border-radius:8px; border:1px solid var(--line); background:radial-gradient(ellipse at 70% 18%,hsl(var(--hue) 65% 43%),transparent 74%),linear-gradient(155deg,#12202f,#0b0b11); }
.poster-art span { padding:.4em; text-align:center; font-weight:850; overflow-wrap:anywhere; }
.poster-art img { position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }
.movie-poster { display:block; }
.reels { display:flex; justify-content:center; gap:clamp(1rem,10vw,10rem); margin:1.5rem 0 3rem; }
.reels section { --team:var(--blue); width:min(34vw,26vh); }
.reels h2 { font-size:clamp(.92rem,2vw,1.8rem); margin-bottom:.6rem; color:var(--team); }
.window { overflow:hidden; aspect-ratio:2/3; border:2px solid var(--team); border-radius:10px; box-shadow:0 0 40px color-mix(in srgb,var(--team) 32%,transparent); }
.strip { animation:spin 4.4s cubic-bezier(.08,.7,.12,1) forwards; }
.red .strip { animation-duration:4.95s; }
@keyframes spin { to { transform:translateY(-95.238095238%); } }
.duel { margin:1.5rem auto 3rem; display:grid; width:min(75rem,100%); grid-template-columns:1fr auto 1fr; align-items:center; gap:clamp(.5rem,4vw,4rem); }
.duel article { min-width:0; transition:transform .7s, opacity .7s; }
.duel article .movie-poster { width:min(100%,27vh); margin:0 auto .75rem; box-shadow:0 0 50px #629dff45; }
.duel .right .movie-poster { box-shadow:0 0 50px #ff566f45; }
.duel small { display:block; color:var(--muted); margin-top:.35rem; }
.reveal article:not(.victor) { opacity:.18; transform:scale(.78); }
.reveal .victor { animation:win-left 1s both; }
.reveal .victor.right { animation-name:win-right; }
.reveal .duel-vs { opacity:0; }
.winner .scene-title { color:var(--gold); animation:appear .5s both; }
.winner::after { content:""; position:absolute; inset:0; background:white; pointer-events:none; animation:flash .65s both; }
@keyframes win-left { to { transform:translateX(55%) scale(1.08); } }
@keyframes win-right { to { transform:translateX(-55%) scale(1.08); } }
@keyframes flash { from { opacity:.55; } to { opacity:0; } }
.skip { position:absolute; bottom:1rem; left:50%; transform:translateX(-50%); white-space:nowrap; }
kbd { background:#ffffff10; border:1px solid var(--line); border-radius:4px; padding:.15em .35em; margin-right:.2em; }
.final-card { width:min(56rem,100%); display:grid; grid-template-columns:minmax(8rem,16rem) 1fr; align-items:center; gap:clamp(1rem,5vw,4rem); padding:clamp(1rem,4vw,3rem); text-align:left; border:1px solid var(--line); border-radius:16px; background:#0c0c14da; }
.actions { display:flex; flex-wrap:wrap; justify-content:center; gap:.7rem; margin:1.4rem 0; }
.final-card .actions { justify-content:flex-start; }
.collection { max-width:75rem; margin:2rem auto; padding:0; display:grid; grid-template-columns:repeat(auto-fill,minmax(120px,1fr)); gap:1rem; list-style:none; text-align:left; counter-reset:rank; }
.collection li { min-width:0; position:relative; counter-increment:rank; }
.collection li::before { content:counter(rank); position:absolute; z-index:1; top:.35rem; left:.35rem; background:#09090ddd; border-radius:4px; padding:.2rem .42rem; }
.collection strong,.collection small { display:block; margin-top:.35rem; }
.collection small,.log time { color:var(--muted); }
.history > button { margin-top:1rem; }
.log { max-width:56rem; margin:2rem auto; padding:0; list-style:none; }
.log li { display:flex; flex-wrap:wrap; gap:.65rem; justify-content:space-between; padding:1rem; border-bottom:1px solid var(--line); }
@media (max-width:650px) {
  header { display:grid; grid-template-columns:1fr auto; gap:.45rem; padding:.55rem .85rem; }
  nav { grid-row:2; grid-column:1 / -1; justify-content:center; }
  .sound { grid-column:2; grid-row:1; }
  .final-card { grid-template-columns:1fr; text-align:center; }
  .final-card .movie-poster { width:min(35vw,10rem); margin:auto; }
  .final-card .actions { justify-content:center; }
}
@media (prefers-reduced-motion:reduce) {
  *, *::before, *::after { animation-duration:.001s !important; transition-duration:.001s !important; }
}
/* Cinema arena */

