 background:radial-gradient(ellipse at 6% 75%,#1645a349,transparent 43%),radial-gradient(ellipse at 94% 75%,#9d302d40,transparent 43%),linear-gradient(180deg,#080a10,#0e1420 85%,#080a10);
 overflow:hidden;
}
