.player::before { content:''; position:absolute; width:210px; height:210px; border:1px solid #87baff17; border-radius:50%; left:50%; top:-80px; transform:translateX(-50%); box-shadow:0 0 0 30px #87baff05,0 0 0 60px #87baff04; }
