/* Film selection drums */
.roulette { padding-top:35px; }
.roulette>.eyebrow { color:#a4adbc; font-size:10px; letter-spacing:.32em; margin-bottom:12px; }
.roulette>h1 { font-size:clamp(30px,4vw,58px); }
.reels { gap:clamp(55px,11vw,170px); position:relative; margin:30px auto 75px; align-items:start; }
.reels::after { content:'VS'; position:absolute; top:49%; left:50%; transform:translate(-50%,-50%) skew(-8deg); font:italic 800 clamp(32px,5vw,72px)/1 Impact,sans-serif; color:#e9ddc9; text-shadow:0 4px 20px #000; }
.reels section { width:min(30vw,30vh); }
.reels h2 { font-family:inherit;font-size:16px;font-weight:700;letter-spacing:.04em;margin-bottom:18px; }
.reels .window {
  position:relative;aspect-ratio:2/3;border:1px solid #ffffff20;border-radius:18px;
  background:#080c14;box-shadow:0 20px 60px #000a,0 0 35px #619aff15;
  overflow:hidden;
}
.reels .red .window { box-shadow:0 20px 60px #000a,0 0 35px #ff615515; }
.reels .window::before,.reels .window::after {
  content:'';position:absolute;left:0;right:0;height:16%;z-index:3;pointer-events:none;
}
.reels .window::before { top:0;background:linear-gradient(#05080ff0,transparent); }
.reels .window::after { bottom:0;background:linear-gradient(transparent,#05080ff0); }
.reels .strip .movie-poster { padding:8px;aspect-ratio:2/3; }
.reels .strip .poster-art { width:100%;height:100%;aspect-ratio:auto;border-radius:10px;box-shadow:0 4px 12px #0008; }
