 .home .matchup { grid-template-columns:1fr 40px 1fr;gap:10px; }
 .home .player h2,.home .player.red h2 { font-size:29px;bottom:25px; }
 .home .player p,.home .player.red p { font-size:9px; }
 .home .home-vs { font-size:42px; }
 .home .hero-logo .brand-logo { width:80vw; }
}
.home .player .avatar.portrait-frame,.home .player.red .avatar.portrait-frame { mask-image:radial-gradient(ellipse 70% 75% at 50% 38%,#000 48%,transparent 94%);-webkit-mask-image:radial-gradient(ellipse 70% 75% at 50% 38%,#000 48%,transparent 94%); }

.movie-poster.already-won .poster-art { filter:grayscale(1);opacity:.48; }
.collection .movie-poster.already-won { position:relative; }
.collection .movie-poster.already-won::after { content:'Уже побеждал';position:absolute;left:0;right:0;bottom:12px;text-align:center;padding:7px 4px;background:#080b12d9;color:#d4d6db;font-size:11px;letter-spacing:.03em;z-index:2; }

/* Ten-second selection with more revolutions. */
.reels .strip { animation-duration:9.4s; }
.reels .red .strip { animation-duration:9.95s; }
.selection-frame { animation-delay:9.4s; }
.red .selection-frame { animation-delay:9.95s; }
@keyframes film-travel {
 from { transform:translateX(0); }
 to { transform:translateX(calc(var(--reel-card) * -44)); }
}
@keyframes film-travel-right {
 from { transform:translateX(calc(var(--reel-card) * -46)); }
 to { transform:translateX(calc(var(--reel-card) * -2)); }
}
@media(prefers-reduced-motion:reduce) {
 .reels .strip,.reels .red .strip { animation-duration:.001s; }
 .selection-frame { animation:none; }
}
